import SwiftUI

struct ComposeView: View {
    @State private var draftText = ""

    var body: some View {
        VStack {
            TextField("message", text: $draftText)
            Button("Send") {
                send()
            }
        }
    }

    private func send() {
        print("sending \(draftText)")
    }
}

